13	// ---- confirm-gate helper for ui2 mutating forms ---------------------------------------------
14	//
15	// Mutating /api routes sit behind the one-time confirmation gate (issue #374's note). A ui2
16	// form cannot mint-and-spend invisibly, so the flow is deliberate and visible:
17	//  1. POST /ui2/<page>/confirm  -> server mints a token for the exact internal call and
18	//     renders a confirmation fragment naming the call.
19	//  2. Operator clicks "Confirm and run" -> POST /ui2/<page>/run with the token -> server
20	//     dispatches the internal call WITH X-Burpsy-Confirm: token and renders the result.
21	//
22	// ui2MintConfirm mints a confirmation for one internal call and returns the token + preview.
23	func (s *Server) ui2MintConfirm(apiPattern, method, url string, body []byte) (token string, preview string, errText string) {
24		call := map[string]any{"method": method, "url": url}
25		if body != nil {
26			if isUTF8Bytes(body) {
27				call["body"] = string(body)
28			} else {
29				call["body_base64"] = base64.StdEncoding.EncodeToString(body)
30			}
31		}
32		payload, _ := ui2Marshal(call)
33		mintURL := strings.TrimRight(apiPattern, "/") + "/confirm"
34		req := newReq(http.MethodPost, mintURL)
35		req.Header.Set("Content-Type", "application/json")
36		req.Body = ioNopCloser(strings.NewReader(string(payload)))
37		rec := newRecorder()
38		// The mint endpoints live on confirmMux (a separate mux the guarded chain consults first);
39		// dispatch the internal mint straight to it — an in-process call needs no origin headers.
40		s.confirmMux.ServeHTTP(rec, req)
41		var minted struct {
42			Token string `json:"token"`
43			Call  struct {
44				Method string `json:"method"`
45				URL    string `json:"url"`
46				Body   string `json:"body"`
47			} `json:"call"`
48		}
49		if err := ui2DecodeJSON(rec.Body.Bytes(), &minted); err != nil {
50			return "", "", "bad mint response: " + err.Error()
51		}
52		preview = fmt.Sprintf("%s %s", minted.Call.Method, minted.Call.URL)
53		if minted.Call.Body != "" {
54			preview += " — body " + truncateForDisplay(minted.Call.Body, 200)
55		}
56		return minted.Token, preview, ""
57	}
58	
59	// ui2DispatchConfirmed runs one internal call with a confirmation token attached.
60	func (s *Server) ui2DispatchConfirmed(method, path string, payload any, token string) (any, string) {
61		var body ioReadCloser
62		if payload != nil {
63			b, _ := ui2Marshal(payload)
64			body = ioNopCloser(strings.NewReader(string(b)))
65		}
66		req := newReq(method, path)
67		if payload != nil {
68			req.Header.Set("Content-Type", "application/json")
69			req.Body = body
70		}
71		if token != "" {
72			req.Header.Set(ConfirmHeader, token)
73		}
74		// The dispatch must pass both gates, so go through s.guarded with the console's own
75		// Host/Origin — the same headers the operator's browser sends.
76		req.Host = "127.0.0.1"
77		req.Header.Set("Origin", "http://127.0.0.1")
78		rec := newRecorder()
79		s.guarded.ServeHTTP(rec, req)
80		if rec.Code == http.StatusPreconditionRequired {
81			return nil, "confirmation required (428) — mint one first"
82		}
83		if rec.Code != http.StatusOK && rec.Code != http.StatusAccepted {
84			return nil, strings.TrimSpace(rec.Body.String())
85		}
86		var result any
87		if err := ui2DecodeJSON(rec.Body.Bytes(), &result); err != nil {
88			return nil, "unreadable response: " + err.Error()
89		}
90		return result, ""
91	}
92	
93	func isUTF8Bytes(b []byte) bool { return string(b) == string(strings.ToValidUTF8(string(b), "")) }
94	
95	func truncateForDisplay(s string, n int) string {
96		if len(s) <= n {
97			return s
98		}
99		return s[:n] + "…"
100	}
