104	// handleUI2Intruder serves GET /ui2/intruder: running attacks + launch form (points from the
105	// selected history exchange), and the run/confirm/run chain for launching an attack.
106	func (s *Server) handleUI2Intruder(w http.ResponseWriter, r *http.Request) {
107		model := map[string]any{}
108		attacks, _ := s.ui2APIResult(http.MethodGet, "/api/intruder/attacks", nil)
109		model["attacks"] = attacks
110		wordlists, _ := s.ui2APIResult(http.MethodGet, "/api/wordlists", nil)
111		model["wordlists"] = wordlists
112		// Latest proxy exchange as the default base request for the launch form.
113		model["base_exchange"], model["base_msgid"], model["base_request"] = ui2LatestExchange(s)
114		ui2Fragment(w, r, "burpsy /ui2/ — Intruder", "intruder", ui2Exec("intruder.html", model))
115	}
