117	// ui2LatestExchange returns the newest non-tool exchange id, the id of its stored request
118	// message (the id /api/intruder/* takes as msg_id), and the raw request text.
119	func ui2LatestExchange(s *Server) (exchID, msgID uint64, raw string) {
120		exs := s.store.Exchanges()
121		for i := len(exs) - 1; i >= 0; i-- {
122			ex := exs[i]
123			switch ex.Source {
124			case "repeater", "intruder", "scanner":
125				continue
126			}
127			if ex.Request != nil {
128				if msg, err := s.store.Get(*ex.Request); err == nil {
129					return uint64(ex.ID), uint64(*ex.Request), string(msg.Raw())
130				}
131			}
132		}
133		return 0, 0, ""
134	}
