136	// handleUI2IntruderPoints serves POST /ui2/intruder/points: enumerate insertion points of the
137	// given exchange (a read API) and render them as checkboxes.
138	func (s *Server) handleUI2IntruderPoints(w http.ResponseWriter, r *http.Request) {
139		_ = r.ParseForm()
140		msgID := r.PostFormValue("msg_id")
141		all := r.PostFormValue("all") == "on" || r.PostFormValue("all") == "true"
142		points, errText := s.ui2APIResult(http.MethodPost, "/api/intruder/points",
143			map[string]any{"msg_id": ui2Atoi(msgID), "all": all})
144		model := map[string]any{"points": points, "error": errText, "msg_id": msgID}
145		w.Header().Set("Content-Type", "text/html; charset=utf-8")
146		_, _ = w.Write([]byte(ui2Exec("intruder_points.html", model)))
147	}
