222	// handleUI2IntruderResults serves GET /ui2/intruder/{id}/results: the attack's sent requests
223	// via the datasets table view.
224	func (s *Server) handleUI2IntruderResults(w http.ResponseWriter, r *http.Request) {
225		id := r.PathValue("id")
226		// The label says newest first, so ask for it (the dataset default is ascending ids), and
227		// forward the page offset: without it every page request returned the same first 200 rows.
228		q := "limit=200&sort_by=id&sort_order=desc"
229		if off := r.URL.Query().Get("offset"); off != "" {
230			q += "&offset=" + url.QueryEscape(off)
231		}
232		res, errText := s.ui2APIResult(http.MethodGet, "/api/datasets/intruder/"+id+"?"+q, nil)
233		model := map[string]any{"task": id, "results": res, "error": errText}
234		w.Header().Set("Content-Type", "text/html; charset=utf-8")
235		if r.Header.Get("HX-Request") == "true" {
236			_, _ = w.Write([]byte(ui2Exec("intruder_results.html", model)))
237			return
238		}
239		ui2RenderPage(w, "burpsy /ui2/ — Attack "+id, "intruder", ui2Exec("intruder_results.html", model))
240	}
