362	
363	// handleUI2Sequencer serves GET /ui2/sequencer: captures list + analyse form.
364	func (s *Server) handleUI2Sequencer(w http.ResponseWriter, r *http.Request) {
365		ui2Fragment(w, r, "burpsy /ui2/ — Sequencer", "sequencer", ui2Exec("sequencer.html", s.ui2SequencerModel()))
366	}
367	
368	// ui2SequencerModel is the page model every Sequencer handler re-renders with: the capture
369	// list and analysis settings, whether any capture is running (drives the control buttons),
370	// and the latest proxy exchange as the start form's prefilled request.
371	func (s *Server) ui2SequencerModel() map[string]any {
372		caps, _ := s.ui2APIResult(http.MethodGet, "/api/sequencer/capture/", nil)
373		settings, _ := s.ui2APIResult(http.MethodGet, "/api/sequencer/settings", nil)
374		model := map[string]any{"captures": caps, "settings": settings}
375		anyRunning := false
376		if m, ok := caps.(map[string]any); ok {
377			if list, ok := m["captures"].([]any); ok {
378				for _, c := range list {
379					if cm, ok := c.(map[string]any); ok {
380						if b, ok := cm["capturing"].(bool); ok && b {
381							anyRunning = true
382						}
383					}
384				}
385			}
386		}
387		model["any_running"] = anyRunning
388		_, _, raw := ui2LatestExchange(s)
389		model["base_request"] = raw
390		return model
391	}
392	
393	// ui2SequencerCapturePayload builds the /api/sequencer/capture body from the start form.
394	// Zero-value count/delay/threads are left for the API's own defaults and validation to
395	// report, so the reviewed body is exactly what the operator typed.
396	func ui2SequencerCapturePayload(r *http.Request) (map[string]any, string) {
397		count, errText := ui2ParseCount("count", r.PostFormValue("count"))
398		delay, err := ui2ParseCount("delay_ms", r.PostFormValue("delay_ms"))
399		if errText == "" {
400			errText = err
401		}
402		threads, err := ui2ParseCount("threads", r.PostFormValue("threads"))
403		if errText == "" {
404			errText = err
405		}
406		loc := map[string]any{"kind": r.PostFormValue("kind")}
407		if n := r.PostFormValue("name"); n != "" {
408			loc["name"] = n
409		}
410		if p := r.PostFormValue("pattern"); p != "" {
411			loc["pattern"] = p
412		}
413		return map[string]any{
414			"target":   r.PostFormValue("target"),
415			"protocol": r.PostFormValue("protocol"),
416			// The textarea round-trips line endings as lone LF; the head must be CRLF on the
417			// wire or many servers never answer (the repeater's ui2RestoreHeaderNewlines).
418			"request":  ui2RestoreHeaderNewlines(r.PostFormValue("request")),
419			"count":    count,
420			"delay_ms": delay,
421			"threads":  threads,
422			"location": loc,
423		}, errText
424	}
425	
426	// handleUI2SequencerCapture serves POST /ui2/sequencer/capture/{action}. "confirm" mints the
427	// one-time review for the exact start call (/api/sequencer/capture is riskAttack - the gate
428	// must see the same body the operator reviewed); "run" spends it; pause/resume/stop drive a
429	// running capture through the API's own control verbs, which are riskRead because stopping
430	// work cannot attack anything.
431	func (s *Server) handleUI2SequencerCapture(w http.ResponseWriter, r *http.Request) {
432		_ = r.ParseForm()
433		switch r.PathValue("action") {
434		case "confirm":
435			payload, errText := ui2SequencerCapturePayload(r)
436			if errText != "" {
437				model := s.ui2SequencerModel()
438				model["error"] = errText
439				ui2Fragment(w, r, "burpsy /ui2/ — Sequencer", "sequencer", ui2Exec("sequencer.html", model))
440				return
441			}
442			body, _ := ui2Marshal(payload)
443			token, preview, errText := s.ui2MintConfirm("/api/sequencer/capture", http.MethodPost, "/api/sequencer/capture", body)
444			model := map[string]any{
445				"token": token, "preview": preview, "error": errText,
446				// The one-line preview is truncated for display; a confirmation gate has to
447				// show the WHOLE exact body it binds, so the sheet carries it in full.
448				"full_body": string(body),
449				"target":    r.PostFormValue("target"), "protocol": r.PostFormValue("protocol"),
450				"count": r.PostFormValue("count"), "delay_ms": r.PostFormValue("delay_ms"),
451				"threads": r.PostFormValue("threads"), "kind": r.PostFormValue("kind"),
452				"name": r.PostFormValue("name"), "pattern": r.PostFormValue("pattern"),
453				"request": r.PostFormValue("request"),
454			}
455			w.Header().Set("Content-Type", "text/html; charset=utf-8")
456			_, _ = w.Write([]byte(ui2Exec("sequencer_confirm.html", model)))
457		case "run":
458			// No dispatch at all without a token: spending a confirmation on a body the operator
459			// never reviewed is the failure this branch exists to prevent.
460			var errText string
461			payload, valErr := ui2SequencerCapturePayload(r)
462			switch {
463			case valErr != "":
464				errText = valErr
465			case r.PostFormValue("token") == "":
466				errText = "no confirmation token: review the capture first"
467			default:
468				_, errText = s.ui2DispatchConfirmed(http.MethodPost, "/api/sequencer/capture", payload, r.PostFormValue("token"))
469			}
470			// The model is built after the dispatch, not before: the operator just started a
471			// capture and the response is the first place they look for its row.
472			model := s.ui2SequencerModel()
473			model["error"] = errText
474			ui2Fragment(w, r, "burpsy /ui2/ — Sequencer", "sequencer", ui2Exec("sequencer.html", model))
475		case "pause", "resume", "stop":
476			_, errText := s.ui2APIResult(http.MethodPost, "/api/sequencer/capture/"+r.PathValue("action"), map[string]any{})
477			model := s.ui2SequencerModel()
478			model["error"] = errText
479			ui2Fragment(w, r, "burpsy /ui2/ — Sequencer", "sequencer", ui2Exec("sequencer.html", model))
480		default:
481			http.Error(w, "unknown capture action", http.StatusBadRequest)
482		}
483	}
484	
485	// handleUI2SequencerAnalyse serves POST /ui2/sequencer/analyse (paste mode, riskRead — no
486	// confirmation needed) rendering the report.
487	func (s *Server) handleUI2SequencerAnalyse(w http.ResponseWriter, r *http.Request) {
488		_ = r.ParseForm()
489		var tokens []string
490		for _, line := range strings.Split(r.PostFormValue("tokens"), "\n") {
491			if t := strings.TrimSpace(line); t != "" {
