510	// recorded interactions.
511	func (s *Server) handleUI2Collaborator(w http.ResponseWriter, r *http.Request) {
512		status, _ := s.ui2APIResult(http.MethodGet, "/api/collaborator/status", nil)
513		inter, _ := s.ui2APIResult(http.MethodGet, "/api/collaborator/interactions", nil)
514		model := map[string]any{"status": status, "interactions": inter}
515		ui2Fragment(w, r, "burpsy /ui2/ — Collaborator", "collaborator", ui2Exec("collaborator.html", model))
516	}
517	
518	// ui2MintTTL is how long a previewed collaborator mint stays confirmable. Same trade as the
519	// confirmation gate's ConfirmTTL: long enough to read and click, short enough that a stale
520	// confirm step refuses instead of minting something the operator stopped looking at.
521	const ui2MintTTL = 60 * time.Second
522	
523	// ui2PendingMint is one previewed collaborator mint, held server-side until its confirm step
524	// spends it. The confirm form carries only the id: the dispatched body is the reviewed one held
525	// here, never re-read form fields, so a count edited between preview and confirm cannot change
526	// what runs (a hidden preview field alone would be client-editable and bind nothing).
527	type ui2PendingMint struct {
528		body    []byte
529		expires time.Time
530	}
531	
532	// handleUI2CollaboratorMint serves POST /ui2/collaborator/mint: mint one payload. The route is
533	// riskEgress, which the confirmation gate does not cover, so no /api/collaborator/payload/confirm
534	// mint endpoint exists: the two-step confirm here is ui2-local. The first POST holds the exact
535	// call server-side and renders it for review; the second (mint_id) spends that held call.
536	func (s *Server) handleUI2CollaboratorMint(w http.ResponseWriter, r *http.Request) {
537		_ = r.ParseForm()
538		status, _ := s.ui2APIResult(http.MethodGet, "/api/collaborator/status", nil)
539		inter, _ := s.ui2APIResult(http.MethodGet, "/api/collaborator/interactions", nil)
540		if id := r.PostFormValue("mint_id"); id != "" {
541			// Confirm step: single-use, and only while fresh. LoadAndDelete spends the id even when
542			// the entry turns out stale, so an expired id cannot be retried into a live one.
543			v, ok := s.ui2Mints.LoadAndDelete(id)
544			mint, isMint := v.(ui2PendingMint)
545			if !ok || !isMint || time.Now().After(mint.expires) {
546				model := map[string]any{"status": status, "interactions": inter,
547					"error": "that confirmation is unknown or has expired — review the call and confirm again"}
548				ui2Fragment(w, r, "burpsy /ui2/ — Collaborator", "collaborator", ui2Exec("collaborator.html", model))
549				return
550			}
551			var body map[string]any
552			if err := ui2DecodeJSON(mint.body, &body); err != nil {
553				model := map[string]any{"status": status, "interactions": inter,
554					"error": "the held call is unreadable — review and confirm again"}
555				ui2Fragment(w, r, "burpsy /ui2/ — Collaborator", "collaborator", ui2Exec("collaborator.html", model))
556				return
557			}
558			result, errText := s.ui2APIResult(http.MethodPost, "/api/collaborator/payload", body)
559			model := map[string]any{"status": status, "interactions": inter, "mint_error": ui2APIErrorText(errText)}
560			// Structured result, not the raw response blob: the operator needs the minted
561			// addresses, the domain they belong to and the correlating marker — copyable —
562			// not a JSON dump that buries them next to config and log noise.
563			if errText == "" {
564				if m, ok := result.(map[string]any); ok {
565					addrs := []string{}
566					if arr, ok := m["addresses"].([]any); ok {
567						for _, a := range arr {
568							if addr, ok := a.(string); ok && addr != "" {
569								addrs = append(addrs, addr)
570							}
571						}
572					}
573					if len(addrs) == 0 {
574						if addr, ok := m["address"].(string); ok && addr != "" {
575							addrs = append(addrs, addr)
576						}
577					}
578					domain, _ := m["domain"].(string)
579					marker, _ := m["marker"].(string)
580					if len(addrs) > 0 {
581						model["minted"] = map[string]any{"addresses": addrs, "domain": domain, "marker": marker}
582						model["mint_error"] = ""
583					} else {
584						model["mint_error"] = "the payload API returned no address — check the channel status below"
585					}
586				}
587			}
588			ui2Fragment(w, r, "burpsy /ui2/ — Collaborator", "collaborator", ui2Exec("collaborator.html", model))
589			return
590		}
591		// Preview step: hold the exact call server-side and render it for review.
592		count := 1
593		if n, err := strconv.Atoi(r.PostFormValue("count")); err == nil && n > 0 && n <= 20 {
594			count = n
595		}
596		payload, _ := ui2Marshal(map[string]any{"count": count})
597		id, err := randomHex(16)
598		if err != nil {
599			model := map[string]any{"status": status, "interactions": inter, "error": "mint id: " + err.Error()}
600			ui2Fragment(w, r, "burpsy /ui2/ — Collaborator", "collaborator", ui2Exec("collaborator.html", model))
601			return
602		}
603		// Sweep expired entries while here; the map stays as small as the number of open tabs.
604		now := time.Now()
605		s.ui2Mints.Range(func(k, v any) bool {
606			if m, ok := v.(ui2PendingMint); ok && now.After(m.expires) {
607				s.ui2Mints.Delete(k)
608			}
609			return true
610		})
611		s.ui2Mints.Store(id, ui2PendingMint{body: payload, expires: now.Add(ui2MintTTL)})
612		model := map[string]any{"status": status, "interactions": inter,
613			"confirm_pending": true, "confirm_preview": "POST /api/collaborator/payload\n" + string(payload),
614			"mint_id": id, "count": count}
615		ui2Fragment(w, r, "burpsy /ui2/ — Collaborator", "collaborator", ui2Exec("collaborator.html", model))
616	}
