618	// ui2RenderSequencerReport renders the sequencer analysis JSON as a readable report —
619	// grade, verdict, entropy figures, per-test outcomes, warnings — never a Go map dump.
620	// Every partial-analysis fact the API reports (FIPS blocks untested, per-position not
621	// computed, significance defaulted, warnings) is carried through, not smoothed over.
622	func ui2RenderSequencerReport(rep any) string {
623		m, ok := rep.(map[string]any)
624		if !ok {
625			return ""
626		}
627		num := func(v any) float64 {
628			f, _ := v.(float64)
629			return f
630		}
631		sub := func(mm map[string]any, k string) map[string]any {
632			v, _ := mm[k].(map[string]any)
633			return v
634		}
635		var sb strings.Builder
636		fmt.Fprintf(&sb, "Grade: %s\n", strOf(m["grade"]))
637		if v := strOf(m["verdict"]); v != "" {
638			fmt.Fprintf(&sb, "Verdict: %s\n", v)
639		}
640		// Provenance: what the sample went through before any figure was computed.
641		// An operator reading a number must know whether the tokens were re-encoded,
642		// decoded, or padded first — a figure over transformed input read as a
643		// figure over the pasted text is a wrong conclusion with a citation.
644		if enc := strOf(m["encoding"]); enc != "" {
645			line := "Encoding: " + enc
646			if d, _ := m["encoding_detected"].(bool); d {
647				line += " (detected from the sample, not chosen by the operator)"
648			}
649			sb.WriteString(line + "\n")
650		}
651		if b, _ := m["base64_decoded"].(bool); b {
652			sb.WriteString("Base64: tokens were base64-decoded to their underlying bytes before analysis - every figure below describes the decoded bytes, not the base64 text\n")
653		}
654		if p := sub(m, "padding"); p != nil {
655			switch strOf(p["mode"]) {
656			case "start", "end":
657				fmt.Fprintf(&sb, "Padding: %v token(s) padded at %s with %s (%v byte(s) added; original token lengths %v..%v)\n",
658					p["tokens_padded"], strOf(p["mode"]), strOf(p["pad_byte_label"]), p["pad_bytes_added"], p["orig_min_len"], p["orig_max_len"])
659			default:
660				sb.WriteString("Padding: none - short tokens are excluded from the positions they do not reach rather than padded with invented characters\n")
661			}
662		}
663		if ee := sub(m, "effective_entropy"); ee != nil {
664			chosen := sub(ee, "chosen")
665			if c, _ := chosen["computed"].(bool); c {
666				line := fmt.Sprintf("Effective entropy: %v bit(s) at %v%% significance",
667					chosen["bits"], ee["significance_percent"])
668				if d, _ := ee["significance_defaulted"].(bool); d {
669					line += " (significance defaulted, not chosen)"
670				}
671				sb.WriteString(line + "\n")
672			} else {
673				// Computed false means Bits is null: printing the figure line
674				// anyway rendered "Effective entropy: <nil>" on samples too small
675				// to support an answer. Name the miss and give the engine's reason.
676				line := "Effective entropy: not computed on this sample"
677				if r := strOf(chosen["reason"]); r != "" {
678					line += " - " + r
679				}
680				sb.WriteString(line + "\n")
681			}
682		}
683		if ws, _ := m["warnings"].([]any); len(ws) > 0 {
684			sb.WriteString("Warnings:\n")
685			for _, w := range ws {
686				fmt.Fprintf(&sb, "- %s\n", strOf(w))
687			}
688		}
689		if c := sub(m, "characters"); c != nil {
690			fmt.Fprintf(&sb, "Characters: %v tokens, lengths %v..%v, alphabet %v, %.2f bits/char, %.2f bits total",
691				num(c["tokens"]), num(c["min_len"]), num(c["max_len"]), num(c["alphabet_size"]),
692				num(c["entropy_bits_per_char"]), num(c["total_entropy_bits"]))
693			if a, _ := c["assumes_positional_independence"].(bool); a {
694				sb.WriteString(" (positional independence assumed)")
695			}
696			sb.WriteByte('\n')
697		}
698		if es := sub(m, "extra_stats"); es != nil {
699			fmt.Fprintf(&sb, "Extra stats: chi-square %v, serial correlation %.4f, Monte Carlo pi %v (deviation %.4f), repeated tokens %v\n",
700				es["chi_square"], num(es["serial_correlation"]), es["monte_carlo_pi"], num(es["monte_carlo_deviation"]), es["repeated_tokens"])
701		}
702		if b := sub(m, "bits"); b != nil {
703			fmt.Fprintf(&sb, "Bits: %v supplied, bit entropy %.4f, longest run %v\n",
704				num(b["bits"]), num(b["bit_entropy"]), num(b["longest_run"]))
705		}
706		if f := sub(m, "fips"); f != nil {
707			fmt.Fprintf(&sb, "FIPS 140-2: %v of %v supplied bits tested (%v-bit blocks, %v complete) - untested bits are not failed bits\n",
708				num(f["bits_tested"]), num(f["bits_supplied"]), num(f["block_bits"]), num(f["blocks_tested"]))
709		}
710		if fp := sub(m, "fips_positions"); fp != nil {
711			if c, _ := fp["computed"].(bool); !c {
712				fmt.Fprintf(&sb, "Per-position significance: not computed - %s\n", strOf(fp["reason"]))
713			}
714		}
715		if adv := sub(m, "advanced"); adv != nil {
716			fmt.Fprintf(&sb, "Extended tests: %s (grade affected: %v)\n", strOf(adv["summary"]), adv["affects_grade"])
717			for _, t := range adv["tests"].([]any) {
718				tm, _ := t.(map[string]any)
719				if tm == nil {
720					continue
721				}
722				name := strOf(tm["name"])
723				if tested, _ := tm["tested"].(bool); !tested {
724					fmt.Fprintf(&sb, "  - %s: not testable on this sample - %s\n", name, strOf(tm["reason"]))
725				} else if passed, _ := tm["passed"].(bool); passed {
726					fmt.Fprintf(&sb, "  - %s: PASS (observed %v, threshold %v)\n", name, tm["observed"], tm["threshold"])
727				} else {
728					fmt.Fprintf(&sb, "  - %s: FAIL (observed %v, flagged %v of %v examined, threshold %v)\n",
729						name, tm["observed"], tm["flagged"], tm["examined"], tm["threshold"])
730				}
731			}
732		}
733		return sb.String()
734	}
735

			durMs = uint64(a.DurationMS)
		}
		s.toolLog.Record(toollog.ToolIntruder, host, port, tls, ex.Method, ex.Path, intOrZero(ex.Status),
			&respLen, durMs, "", &ex.ID)
	}
}

func intruderRedirectPolicy(mode *string, standing sender.RedirectSettings) (sender.RedirectSettings, error) {
	if mode == nil || *mode == "" {
		return standing, nil
	}
	switch sender.RedirectMode(*mode) {
	case sender.RedirectNever, sender.RedirectOnSite, sender.RedirectInScope, sender.RedirectAlways:
		return sender.RedirectSettings{Mode: sender.RedirectMode(*mode), MaxHops: standing.MaxHops}, nil
	default:
		return sender.RedirectSettings{}, fmt.Errorf(
			"follow_redirects: unknown mode %q (want never, on_site, in_scope, always, or empty for the standing policy)", *mode)
	}
}

// AttemptView is the legacy one-position form's row.
type AttemptView struct {
	Payload     string  `json:"payload"`
	Status      *int    `json:"status"`
	Len         int     `json:"len"`
	DurationMS  uint64  `json:"duration_ms"`
	Error       *string `json:"error"`
	GrepMatched *bool   `json:"grep_matched"`
	GrepExtract *string `json:"grep_extract"`
	// GrepMatchCounts is the expression list's per-item occurrence count (irt). Empty when no
	// list was configured.
	GrepMatchCounts []int `json:"grep_match_counts"`
}

// BucketExample resolves one ordinal — a bucket's first ordinal, or any other attempt ordinal the
// report kept — back to the exact payload combination the engine actually sent, so the operator
// never has to reconstruct it by hand. FirstOrdinal is the field name for historical reasons (the
// bucket table was the first consumer); despite the name, RunView.Examples carries one entry per
// distinct ordinal across both the bucket table and the attempts table.
type BucketExample struct {
	FirstOrdinal int      `json:"first_ordinal"`
	Payloads     []string `json:"payloads"`
}

// RunView is the full report shape: the bucketed summary, payloads behind every bucket and every
// kept attempt (keyed by ordinal in Examples — see BucketExample), and the honest per-set
// counting (what was capped, truncated, skipped or dropped).
type RunView struct {
	// TaskID is the dashboard task this attack ran as — the id its results page
	// (/ui2/intruder/{id}/results, /api/datasets/intruder/{id}) is keyed by. The attack's
	// registry entry is removed the moment this response is written, so without it a caller
	// whose attack has finished has no handle on its results.
	TaskID      uint64                `json:"task_id"`
	Report      intruder.AttackReport `json:"report"`
	Examples    []BucketExample       `json:"examples"`
	PayloadSets []intruder.PayloadSet `json:"payload_sets"`
	// SessionCookies says what the session cookie jar contributed to this attack. Always present, so
	// "the jar was empty" and "the jar was never consulted" are not the same JSON — the reading that
	// makes a whole unauthenticated attack look like a finding about the endpoint.
	SessionCookies intruderSessionCookies `json:"session_cookies"`
	// RedirectsFollowed is how many additional requests this attack sent chasing a 3xx, summed
	// across every attempt (tirx). Zero whenever follow_redirects names RedirectNever (the default)
	// or every hop was refused by policy or scope — the same "prove the setting did something"
	// discipline AutoThrottleEngaged already holds the rate limiter to.
	RedirectsFollowed int `json:"redirects_followed"`
	// ConnectionsOpened and ConnectionsReused are what HTTP/1 connection reuse did (xhqr): sockets
	// this attack dialled, and requests that completed on a socket an earlier request had used. Both
	// null when reuse was off — every request then had a connection of its own and nothing was
	// counted — so "reuse was off" and "reuse was on and never happened" are different JSON. Redirect
	// hops always dial their own connection and are in neither count.
	ConnectionsOpened *int64 `json:"connections_opened"`
	ConnectionsReused *int64 `json:"connections_reused"`
	// HostHeaderUpdated says "Update Host header to match target" (ety8) was applied: every request's
	// Host header was rewritten to the target authority, except the HostHeaderUntouched ones.
	// HostHeaderSkipped is why it was not applied at all when it was asked for — a position covers
	// the Host header, or the base request does not carry exactly one — and empty otherwise.
	// HostHeaderUntouched counts requests a payload left with other than one Host header, which were
	// sent as spliced rather than rewritten: a payload that adds a Host header is a probe, and
	// choosing which of two to rewrite would change what it tests.
	HostHeaderUpdated   bool   `json:"host_header_updated"`
	HostHeaderSkipped   string `json:"host_header_skipped"`
	HostHeaderUntouched int    `json:"host_header_untouched"`
}

// intruderSessionCookies reports the jar's contribution to one attack, by cookie name.
//
// Names only. Values are session tokens by construction, and an attack report is a document that gets
// pasted into tickets — the same reason Coordinator.logExtraction never logs a resolved value.
type intruderSessionCookies struct {
	// Attached are the jar cookie names merged into every request, sorted.
	Attached []string `json:"attached"`
	// Exempt are cookie names the attack is fuzzing, which the jar deliberately did not overwrite.
	// Burp's rule; see internal/web/intruder_cookies.go.
	Exempt []string `json:"exempt"`
	// JarEmpty distinguishes "the jar holds nothing for this authority" from "nothing was attached
	// because every jar cookie was a fuzzed position". Both give an empty Attached list and mean
	// different things about whether the attack was authenticated.
	JarEmpty bool `json:"jar_empty"`
}

// intruderSessionCookieView builds the report from the same two inputs the send path used, so the
// report cannot claim a cookie the wire did not carry.
func intruderSessionCookieView(jarHeader string, exempt map[string]bool) intruderSessionCookies {
	out := intruderSessionCookies{
		Attached: []string{},
		Exempt:   []string{},
		JarEmpty: jarHeader == "",
	}
	for name := range exempt {
		out.Exempt = append(out.Exempt, name)
	}
	for _, p := range parseCookieHeader(jarHeader) {
		if p.name == "" || exempt[strings.ToLower(p.name)] {
			continue
		}
		out.Attached = append(out.Attached, p.name)
	}
	sort.Strings(out.Attached)
	sort.Strings(out.Exempt)
	return out
}

