package web

import (
	"encoding/json"
	"net/http"
	"sort"
	"strconv"
	"sync"

	"github.com/burpsy-go/burpsy/internal/dash"
	"github.com/burpsy-go/burpsy/internal/intruder"
)

// Pausing, resuming and stopping a running Intruder attack.
//
// # The gap
//
// Only two Intruder routes existed, /points and /run, so a launched attack could not be reached at
// all. Worse, /run registered its dashboard task without calling dash.Handle.WithCancel — while the
// package doc for WithCancel already named "intruder attack stop" as one of its three consumers — so
// Task.Cancellable() was false for every attack and the dashboard rendered no stop button either. A
// cluster bomb bounded at the 200,000-request ceiling and aimed at the wrong host could be halted only
// by killing the process.
//
// # Why the run handler stayed synchronous
//
// intruder.Run is called inside the /run handler and its report is that request's response. Making the
// attack a background job would change /run's contract and every client of it, which is a UI change
// and not this one. So the attack is registered while it runs, and pause/resume/stop act on it from
// another connection. A paused attack holds /run's response open, which is the honest consequence: the
// report does not exist yet.
//
// The remaining half is UI: intruder.tsx needs an AbortController on its run mutation (useRepeaterSend
// in the same file already has one) and controls wired to these routes. The dashboard stop button
// works today, because the task is now cancellable.

// runningAttack is one attack the process is executing, as the control routes see it.
type runningAttack struct {
	taskID  uint64
	kind    string
	target  string
	planned int
	control *intruder.Control
}

// attackRegistry is the live table of attacks that can be controlled.
//
// Keyed by dashboard task id, deliberately: the dashboard is where an operator sees a running attack,
// so the handle they already have is the handle these routes take. Inventing a second id space would
// mean the stop button on the dashboard and the stop button in Intruder addressed the same attack by
// different names.
type attackRegistry struct {
	mu sync.RWMutex
	m  map[uint64]*runningAttack
}

func newAttackRegistry() *attackRegistry { return &attackRegistry{m: map[uint64]*runningAttack{}} }

// register starts the attack's dashboard task and records the attack in one step, under the
// registry's write lock, and returns the task. start runs with the lock held: it is where the caller
// calls tasks.Start and builds the attack from the new task's id.
//
// Two separate steps left a window in which the task was on the dashboard — with its id, which is the
// handle the control routes take — while GET /api/intruder/attacks did not list it and
// /api/intruder/attacks/{id}/stop answered 404 (burpsy-react-ui-h68z; it surfaced as
// TestIntruderAttacksListsARunningAttackAndStopEndsIt failing under -race's slower scheduling).
// Holding the lock across both closes it: a reader that saw the task and then asks this registry
// blocks on the lock until the attack is in it.
func (r *attackRegistry) register(start func() (*dash.Handle, *runningAttack)) *dash.Handle {
	r.mu.Lock()
	defer r.mu.Unlock()
	task, a := start()
	if a != nil && a.taskID != 0 {
		r.m[a.taskID] = a
	}
	return task
}

// remove drops an attack that has ended. Called from the run handler's defer, so an attack that
// panicked is still removed — a table entry whose attack is gone would offer a stop button that
// silently does nothing, which is the failure the dash registry's Cancellable() exists to prevent.
func (r *attackRegistry) remove(taskID uint64) {
	if r == nil {
		return
	}
	r.mu.Lock()
	delete(r.m, taskID)
	r.mu.Unlock()
}

func (r *attackRegistry) get(taskID uint64) *runningAttack {
	if r == nil {
		return nil
	}
	r.mu.RLock()
	defer r.mu.RUnlock()
	return r.m[taskID]
}

func (r *attackRegistry) snapshot() []*runningAttack {
	if r == nil {
		return nil
	}
	r.mu.RLock()
	out := make([]*runningAttack, 0, len(r.m))
	for _, a := range r.m {
		out = append(out, a)
	}
	r.mu.RUnlock()
	sort.Slice(out, func(i, j int) bool { return out[i].taskID < out[j].taskID })
	return out
}

// intruderAttackView is one running attack on the wire.
type intruderAttackView struct {
	// TaskID is the dashboard task id, which is also the id the control routes take.
	TaskID  uint64 `json:"task_id"`
	Kind    string `json:"kind"`
	Target  string `json:"target"`
	Planned int    `json:"planned"`
	// Status is "running", "paused" or "stopped". A stopped attack can still appear here briefly,
	// while its in-flight sends land and its report is assembled: reporting it as running would be a
	// state the operator can no longer act on, and dropping it early would make a stop look like it
	// had not happened.
	Status string `json:"status"`
	// StopReason is why it was stopped, empty when it was not.
	StopReason string `json:"stop_reason,omitempty"`
	// Sent and Failed are the sends that have settled so far — the live answer to "is it doing
	// anything", and the same totals the eventual report carries. planned bounds sent+failed only
	// loosely: a stop lets in-flight sends land, so an ended attack's counts can still move.
	Sent   int `json:"sent"`
	Failed int `json:"failed"`
}

func attackView(a *runningAttack) intruderAttackView {
	sent, failed := a.control.Progress()
	return intruderAttackView{
		TaskID: a.taskID, Kind: a.kind, Target: a.target, Planned: a.planned,
		Status:     string(a.control.Status()),
		StopReason: a.control.StopReason(),
		Sent:       sent,
		Failed:     failed,
	}
}

// intruderAttacksResp is the list shape. Attacks is never null, so a client cannot read "the field is
// missing" as "there are none".
type intruderAttacksResp struct {
	Attacks []intruderAttackView `json:"attacks"`
}

// handleIntruderAttacks serves GET /api/intruder/attacks: every attack this process is running and
// can be controlled.
func (s *Server) handleIntruderAttacks(w http.ResponseWriter, r *http.Request) {
	running := s.attacks.snapshot()
	out := make([]intruderAttackView, 0, len(running))
	for _, a := range running {
		out = append(out, attackView(a))
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(intruderAttacksResp{Attacks: out})
}

// handleIntruderAttackAction serves POST /api/intruder/attacks/{task_id}/{pause|resume|stop}.
//
// The three failure answers are kept distinct, for the reason dash.Registry.Cancel keeps its three
// apart: "no such attack" (404) means the id is wrong or the attack has finished, while "the attack is
// already over" (409) means the id was right and the action cannot apply. Collapsing them into one
// success — the shape /api/sequencer/stop used to have before it grew a real loop to stop — is how a
// stop button that does nothing reads as a stop button that worked.
// handleIntruderAttackNoAction is the old handler's first answer, kept for the two shapes with no
// action segment: "/api/intruder/attacks/" and "/api/intruder/attacks/{id}".
func (s *Server) handleIntruderAttackNoAction(w http.ResponseWriter, r *http.Request) {
	http.Error(w, "Expected /api/intruder/attacks/{task_id}/{pause|resume|stop}", http.StatusNotFound)
}

func (s *Server) handleIntruderAttackAction(w http.ResponseWriter, r *http.Request) {
	// {action...} keeps the old Cut-at-first-slash contract: "stop/" and "stop/extra" arrive as the
	// action text, so their "Unknown action" bodies are the ones the old subtree handler wrote.
	idStr, action := r.PathValue("id"), r.PathValue("action")
	id, err := strconv.ParseUint(idStr, 10, 64)
	if err != nil {
		http.Error(w, "Invalid task id", http.StatusNotFound)
		return
	}
	attack := s.attacks.get(id)
	if attack == nil {
		http.Error(w, "No running attack with that task id", http.StatusNotFound)
		return
	}

	var changed bool
	switch action {
	case "pause":
		changed = attack.control.Pause()
	case "resume":
		changed = attack.control.Resume()
	case "stop":
		changed = attack.control.Stop("stopped by the operator")
	default:
		http.Error(w, "Unknown action "+strconv.Quote(action)+": expected pause, resume or stop",
			http.StatusNotFound)
		return
	}
	if !changed {
		// The attack exists and the action cannot apply: it has already stopped, or its plan is
		// exhausted and its report is being assembled. Named as a conflict rather than reported as a
		// success on a state that did not change.
		writeJSON(w, http.StatusConflict, map[string]any{
			"task_id": id,
			"action":  action,
			"applied": false,
			"status":  string(attack.control.Status()),
			"reason":  "the attack is no longer in a state this action can change",
		})
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"task_id": id,
		"action":  action,
		"applied": true,
		"status":  string(attack.control.Status()),
	})
}

import { emptyIntruderConfig, type GrepMatchMode, type IntruderConfig } from "./store";
import { ATTACK_MODES, PAYLOAD_RULES } from "./types.tools";

/**
 * Burp's "Save attack config" / "Load attack config", as a file this browser writes and reads.
 *
 * Burp keeps an attack configuration in the project file; burpsy has no project file, so the
 * carrier is a JSON document the operator downloads and picks back up. That is only honest if the
 * document holds EVERY field the Intruder page holds — a loader that silently drops the payload
 * processing rules would hand back an attack that looks like the saved one and sends different
 * requests. So the format is the whole `IntruderConfig`, and the reader refuses a document it
 * cannot restore in full, naming the field, rather than filling the gap with a default.
 *
 * The field table below is typed `Record<keyof IntruderConfig, Check>`: adding a field to
 * IntruderConfig without adding a check here is a type error, not a silently unsaved field.
 */

export const ATTACK_CONFIG_FORMAT = "burpsy-intruder-attack";
export const ATTACK_CONFIG_VERSION = 1;

/** What a save writes and a load expects. */
export interface AttackConfigFile {
 format: string;
 version: number;
 config: IntruderConfig;
}

/** A field check: null when the value is restorable, otherwise the reason it is not. */
type Check = (value: unknown) => string | null;

/** Burp's auto-pause condition: pause when an expression APPEARS, or when it stops appearing. */
export const AUTO_PAUSE_MODES = ["appears", "missing"] as const;

const ATTACK_MODE_VALUES = ATTACK_MODES.map((mode) => mode.value) as string[];
const PAYLOAD_RULE_VALUES = PAYLOAD_RULES.map((rule) => rule.value) as string[];
const PAYLOAD_TYPE_VALUES = ["list", "numbers", "file", "brute_force", "dates", "custom_iterator", "null"] as string[];
const GREP_MATCH_MODES: GrepMatchMode[] = ["simple", "regex"];

function isPlainObject(value: unknown): value is Record<string, unknown> {
 return typeof value === "object" && value !== null && !Array.isArray(value);
}

const str: Check = (value) => (typeof value === "string" ? null : `expected a string, found ${typeName(value)}`);
const bool: Check = (value) => (typeof value === "boolean" ? null : `expected true or false, found ${typeName(value)}`);
/** Finite numbers only: NaN and Infinity survive neither JSON nor the run request. */
const num: Check = (value) => (typeof value === "number" && Number.isFinite(value) ? null : `expected a number, found ${typeName(value)}`);
const int: Check = (value) =>
 typeof value === "number" && Number.isInteger(value) ? null : `expected a whole number, found ${typeName(value)}`;

function typeName(value: unknown): string {
 if (value === null) return "null";
 if (Array.isArray(value)) return "an array";
 if (typeof value === "string") return `the string ${JSON.stringify(value)}`;
 if (typeof value === "number" || typeof value === "boolean") return String(value);
 if (value === undefined) return "nothing";
 return "an object";
}

function oneOf(allowed: string[]): Check {
 return (value) => {
  if (typeof value !== "string") return `expected one of ${allowed.join(", ")}, found ${typeName(value)}`;
  return allowed.includes(value) ? null : `${JSON.stringify(value)} is not one of ${allowed.join(", ")}`;
 };
}

function arrayOf(item: Check): Check {
 return (value) => {
  if (!Array.isArray(value)) return `expected an array, found ${typeName(value)}`;
  for (let i = 0; i < value.length; i++) {
   const reason = item(value[i]);
   if (reason) return `[${i}] ${reason}`;
  }
  return null;
 };
}

/** An object with exactly these keys — an extra key means the writer knew something this reader does not. */
function shape(fields: Record<string, Check>): Check {
 const expected = Object.keys(fields);
 return (value) => {
  if (!isPlainObject(value)) return `expected an object, found ${typeName(value)}`;
  for (const key of Object.keys(value)) {
   if (!expected.includes(key)) return `has an unknown key ${JSON.stringify(key)}`;
  }
  for (const key of expected) {
   if (!(key in value)) return `is missing ${JSON.stringify(key)}`;
   const reason = fields[key]!(value[key]);
   if (reason) return `.${key} ${reason}`;
  }
  return null;
 };
}

/**
 * `shape` plus keys that may be absent. A key that is present is checked like any other, and an
 * absent one is fine: only a "plugin" processing rule carries `plugin`, and the other rules must
 * keep the exact key set they have always been saved with (burpsy-react-ui-0qwh).
 */
function shapeWithOptional(fields: Record<string, Check>, optional: Record<string, Check>): Check {
 const strict = shape(fields);
 return (value) => {
  if (!isPlainObject(value)) return strict(value);
  const present = Object.keys(optional).filter((key) => key in value);
  const rest: Record<string, unknown> = { ...value };
  for (const key of present) {
   const reason = optional[key]!(value[key]);
   if (reason) return `.${key} ${reason}`;
   delete rest[key];
  }
  return strict(rest);
 };
}

/**
 * One check per IntruderConfig field. The `Record<keyof IntruderConfig, …>` annotation is the
 * guard that matters: a new attack-configuration field that nobody adds here fails `tsc`, so the
 * file format cannot fall behind the page without the build saying so.
 */
const CHECKS: Record<keyof IntruderConfig, Check> = {
 msgId: str,
 target: str,
 label: str,
 mode: oneOf(ATTACK_MODE_VALUES),
 allPoints: bool,
 points: arrayOf(
  shape({ index: int, kind: str, label: str, offset: int, len: int, current: str, placement: oneOf(["replace", "append"]) }),
 ),
 selected: arrayOf(int),
 payloadTexts: arrayOf(str),
 payloadTypes: arrayOf(oneOf(PAYLOAD_TYPE_VALUES)),
 payloadNumbers: arrayOf(shape({ from: str, to: str, step: str })),
 payloadFiles: arrayOf(str),
 payloadBrute: arrayOf(shape({ charset: str, min_len: str, max_len: str })),
 payloadDates: arrayOf(shape({ from: str, to: str, step: str, format: str })),
 payloadCustom: arrayOf(shape({ positions: str, separator: str })),
 payloadNulls: arrayOf(str),
 rules: arrayOf(
  shapeWithOptional(
   {
    rule: oneOf(PAYLOAD_RULE_VALUES),
    text: str,
    pattern: str,
    replace: str,
    all: bool,
    layer: str,
    algorithm: str,
    form: str,
   },
   { plugin: shape({ plugin: str, registration: str }) },
  ),
 ),
 grepMatch: str,
 grepMatchMode: oneOf(GREP_MATCH_MODES),
 grepExtract: str,
 poolName: str,
 maxRequests: num,
 maxInFlight: num,
 rps: str,
 // Fields the page grew after this format was first written. They are here because the guard
 // above made adding them compulsory rather than optional: a saved attack that silently dropped
 // its manual markers or its rate variation would reload as a DIFFERENT attack that looks like
 // the saved one — the precise failure this file exists to prevent.
 manualSpans: arrayOf(shape({ start: int, end: int, text: str })),
 grepMatchList: arrayOf(str),
 grepMatchCaseSensitive: bool,
 grepMatchExcludeHeaders: bool,
 // Grep - Payloads (7qc3).
 grepPayloadsEnabled: bool,
 grepPayloadsCaseSensitive: bool,
 grepPayloadsExcludeHeaders: bool,
 grepPayloadsMatchPreEncoded: bool,
 // The results capture filter (ip2b).
 captureFilterEnabled: bool,
 captureDiscardNoResponse: bool,
 captureTerm: str,
 captureRegex: bool,
 captureCaseSensitive: bool,
 captureNegate: bool,
 captureStatuses: arrayOf(oneOf(["2xx", "3xx", "4xx", "5xx"])),
 // Store requests / Store responses (nqww).
 storeRequests: bool,
 storeResponses: bool,
 // The resource pool's delay variation (burpsy-react-ui-nn0n). Held as text by the page, so saved
 // as text: "" is "not set", which is not the same attack as an explicit 0.
 delayJitterPct: str,
 delayIncrementMS: str,
 retries: str,
 retryDelayMS: str,
 baseline: bool,
 // Burp's Set Connection header and Store full payloads (fmxv). Booleans, like baseline: an
 // attack either sends Connection: close on every request or it does not, and there is no
 // third state a saved configuration could be in.
 setConnectionClose: bool,
 storePayloads: bool,
 // Burp's per-request response timeout (mmca). Text, like retries: "" is "the standing read
 // timeout", which is not the same attack as any number.
 responseTimeoutMS: str,
 // HTTP/1 connection reuse and the HTTP version override (xhqr).
 http1ConnectionReuse: bool,
 httpVersion: oneOf(["", "http1", "http2"]),
 // Update Host header to match target (ety8).
 updateHostHeader: bool,
 // Automatic payload placement (1krs): the saved points were measured under it, so it is saved too.
 payloadPlacement: oneOf(["replace", "append"]),
 // Burp's auto-pause (2cvk). The block is saved whole, enabled flag first, because a saved
 // configuration that dropped it would resume as a different attack that looks like the saved
 // one — the exact failure this file exists to prevent, and the one fmxv's settings had.
 autoPauseEnabled: bool,
 autoPauseMode: oneOf([...AUTO_PAUSE_MODES]),
 autoPauseExpressions: arrayOf(str),
 autoPauseSimple: bool,
 autoPauseCaseSensitive: bool,
};

/** The fields a saved attack configuration carries, in the order the store declares them. */
export const ATTACK_CONFIG_FIELDS = Object.keys(emptyIntruderConfig()) as (keyof IntruderConfig)[];

/** The whole configuration as a document, pretty-printed because an operator reads and diffs these. */
export function serializeAttackConfig(config: IntruderConfig): string {
 const ordered: Record<string, unknown> = {};
 // Written in the store's declaration order rather than whatever order the live object acquired,
 // so two saves of the same attack are byte-identical and `diff` says what actually changed.
 for (const key of ATTACK_CONFIG_FIELDS) ordered[key] = config[key];
 const file: Record<string, unknown> = {
  format: ATTACK_CONFIG_FORMAT,
  version: ATTACK_CONFIG_VERSION,
  config: ordered,
 };
 return `${JSON.stringify(file, null, 2)}\n`;
}

export type AttackConfigParse = { ok: true; config: IntruderConfig } | { ok: false; reason: string };

/**
 * Read a saved attack configuration, or refuse it saying which field stopped the load.
 *
 * Refusal is the whole point. A loader that skipped an unreadable field would leave the page
 * holding a mixture of the file and whatever was there before, which is an attack configuration
 * nobody wrote — and the operator would find out by reading a report produced by requests they did
 * not intend. Unknown keys are refused for the same reason in the other direction: a file written
 * by a newer burpsy carries settings this one would drop on the floor.
 */
export function parseAttackConfig(text: string): AttackConfigParse {
 let parsed: unknown;
 try {
  parsed = JSON.parse(text);
 } catch (error) {
  return { ok: false, reason: `This is not JSON: ${error instanceof Error ? error.message : String(error)}` };
 }
 if (!isPlainObject(parsed)) {
  return { ok: false, reason: `A saved attack configuration is a JSON object; this file holds ${typeName(parsed)}.` };
 }
 if (parsed.format !== ATTACK_CONFIG_FORMAT) {
  return {
   ok: false,
   reason: `"format" is ${typeName(parsed.format)}, not ${JSON.stringify(ATTACK_CONFIG_FORMAT)} — this is not a burpsy Intruder attack configuration.`,
  };
 }
 if (parsed.version !== ATTACK_CONFIG_VERSION) {
  return {
   ok: false,
   reason: `"version" is ${typeName(parsed.version)}; this burpsy reads version ${ATTACK_CONFIG_VERSION} only.`,
  };
 }
 const raw = parsed.config;
 if (!isPlainObject(raw)) {
  return { ok: false, reason: `"config" is ${typeName(raw)}, not an object.` };
 }
 for (const key of Object.keys(raw)) {
  if (!(ATTACK_CONFIG_FIELDS as string[]).includes(key)) {
   return {
    ok: false,
    reason: `"config" carries ${JSON.stringify(key)}, which this burpsy does not know how to restore. Refusing rather than dropping it.`,
   };
  }
 }
 for (const key of ATTACK_CONFIG_FIELDS) {
  if (!(key in raw)) {
   return { ok: false, reason: `"config.${key}" is missing, so this attack cannot be restored in full.` };
  }
  const reason = CHECKS[key](raw[key]);
  if (reason) return { ok: false, reason: `"config.${key}" ${reason}.` };
 }
 const config = {} as Record<string, unknown>;
 for (const key of ATTACK_CONFIG_FIELDS) config[key] = raw[key];
 return { ok: true, config: config as unknown as IntruderConfig };
}

/** A filename that sorts by save time and says what it is. */
export function attackConfigFilename(now: Date = new Date()): string {
 const stamp = now.toISOString().replace(/[:.]/g, "-").replace(/Z$/, "");
 return `burpsy-attack-${stamp}.json`;
}

