    }
    liveBusy = false;
    if (name === 'htmx:afterRequest' && liveTrailing) {
      var w = liveTrailing;
      liveTrailing = '';
      liveRefresh(w);
    } else if (name !== 'htmx:afterRequest') {
      liveTrailing = '';
    }
  });
});

